-- Focused ECMAScript professional string contract regression; reusable by D0 in one backend.
BEGIN;
DO $$ BEGIN IF current_setting('maiprop.test_disposable_database',true) IS DISTINCT FROM current_database()
 OR inet_server_addr() IS NOT NULL OR current_database() IN ('postgres','template0','template1','maiprop_replay_current_20260921')
 THEN RAISE EXCEPTION 'Explicit disposable local socket database required'; END IF; END $$;
CREATE EXTENSION IF NOT EXISTS pgtap;
SELECT no_plan();
SET LOCAL session_replication_role=replica;
INSERT INTO auth.users(id) VALUES('7c090000-0000-4000-8000-000000000001');
INSERT INTO public.profiles(user_id,role,participant_type) VALUES('7c090000-0000-4000-8000-000000000001','buyer','buyer');
SET LOCAL session_replication_role=origin;
RESET ROLE; SET LOCAL ROLE service_role; SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
-- Exact ECMAScript WhiteSpace and LineTerminator code points, individually rejected as a required title.
SELECT throws_ok(format($rpc$SELECT public.complete_onboarding_role_with_profile_for_user('7c090000-0000-4000-8000-000000000001','buyer','buyer',NULL,NULL,NULL,jsonb_build_object('title',chr(%s),'category','architect'))$rpc$,cp),'22023','invalid_professional_profile','blank title U+'||to_hex(cp))
FROM unnest(ARRAY[9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279]) cp;
RESET ROLE; SET LOCAL ROLE postgres;
SELECT is((SELECT count(*)::int FROM public.professionals WHERE user_id='7c090000-0000-4000-8000-000000000001'),0,'rejected blank titles never insert');
RESET ROLE; SET LOCAL ROLE service_role; SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT lives_ok($rpc$SELECT public.complete_onboarding_role_with_profile_for_user('7c090000-0000-4000-8000-000000000001','buyer','buyer',NULL,NULL,NULL,jsonb_build_object('title',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'||'Architect'||U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF','category','architect','displayName',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF','city',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'||'Athens'||U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF','licenseNumber',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))$rpc$,'full JS trim set accepted around content');
RESET ROLE; SET LOCAL ROLE postgres;
SELECT ok((SELECT title='Architect' AND display_name IS NULL AND city='Athens' AND license_number IS NULL FROM public.professionals WHERE user_id='7c090000-0000-4000-8000-000000000001'),'all optional fields normalize Unicode whitespace and blank to null');
RESET ROLE; SET LOCAL ROLE service_role; SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT lives_ok($rpc$SELECT public.complete_onboarding_role_with_profile_for_user('7c090000-0000-4000-8000-000000000001','buyer','buyer',NULL,NULL,NULL,jsonb_build_object('title','Architect','category','architect')||jsonb_build_object('title',repeat(chr(128512),80)))$rpc$,'title accepts exact UTF16 boundary');
RESET ROLE; SET LOCAL ROLE postgres;
SELECT is((SELECT title FROM public.professionals WHERE user_id='7c090000-0000-4000-8000-000000000001'),repeat(chr(128512),80),'title boundary persisted exactly');
CREATE TEMP TABLE string_contract_before AS SELECT to_jsonb(p) AS row FROM public.professionals p WHERE user_id='7c090000-0000-4000-8000-000000000001';
RESET ROLE; SET LOCAL ROLE service_role; SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT throws_ok($rpc$SELECT public.complete_onboarding_role_with_profile_for_user('7c090000-0000-4000-8000-000000000001','buyer','buyer',NULL,NULL,NULL,jsonb_build_object('title','Architect','category','architect')||jsonb_build_object('title',repeat(chr(128512),80)||'x'))$rpc$,'22023','invalid_professional_profile','title rejects mixed one-unit overflow');
SELECT throws_ok($rpc$SELECT public.complete_onboarding_role_with_profile_for_user('7c090000-0000-4000-8000-000000000001','buyer','buyer',NULL,NULL,NULL,jsonb_build_object('title','Architect','category','architect')||jsonb_build_object('title',repeat(chr(128512),81)))$rpc$,'22023','invalid_professional_profile','title rejects supplementary overflow');
RESET ROLE; SET LOCAL ROLE postgres;
SELECT is((SELECT to_jsonb(p) FROM public.professionals p WHERE user_id='7c090000-0000-4000-8000-000000000001'),(SELECT row FROM string_contract_before),'title failed calls preserve entire professional row');
